function useInfiniteFeed() {
  const [items, setItems] = useState<Post[]>([]);
  const [cursor, setCursor] = useState<string | null>(null);
  const sentinel = useRef<HTMLDivElement>(null);
  const loadingRef = useRef(false);

  const loadMore = async (from: string | null) => {
    if (loadingRef.current) return;
    loadingRef.current = true;
    try {
      const page = await fetchFeed(from);
      setItems((prev) => [...prev, ...page.items]);
      setCursor(page.nextCursor);
    } finally {
      loadingRef.current = false;
    }
  };

  useEffect(() => {
    const io = new IntersectionObserver(
      ([entry]) => {
        if (entry.isIntersecting) void loadMore(cursor);
      },
      { rootMargin: '600px' }
    );

    if (sentinel.current) io.observe(sentinel.current);
    return () => io.disconnect();
  }, []);

  return { items, sentinel };
}

referenceAnswer:
The in-flight guard is already in place, which is why the symptom is a repeat rather than a storm — the cursor is the defect. The IntersectionObserver callback is created inside an effect with `[]` deps, so it captures `cursor` from the first render (`null`) and keeps calling `loadMore(null)`. Fix: keep the cursor in a ref that the callback reads at call time, so the observer stays subscribed across pages:

```tsx
const cursorRef = useRef<string | null>(null);

const loadMore = async () => {
  if (loadingRef.current) return;
  loadingRef.current = true;
  try {
    const page = await fetchFeed(cursorRef.current);
    cursorRef.current = page.nextCursor;
    setItems((prev) => [...prev, ...page.items]);
  } finally {
    loadingRef.current = false;
  }
};
```

Adding `cursor` to the effect's deps also works, at the cost of tearing down and re-creating the observer on every page; re-observing a still-visible sentinel fires immediately, which with the guard in place simply loads the next page.

