class ChatSocket {
  private ws: WebSocket | null = null;
  private queue: string[] = [];
  private attempt = 0;

  constructor(private url: string) {
    this.connect();
  }

  private connect() {
    this.ws = new WebSocket(this.url);

    this.ws.addEventListener('open', () => {
      this.attempt = 0;
      const pending = this.queue;
      this.queue = [];
      for (const message of pending) this.ws!.send(message);
    });

    this.ws.addEventListener('close', () => {
      const ceiling = Math.min(1000 * 2 ** this.attempt++, 30000);
      setTimeout(() => this.connect(), Math.random() * ceiling);
    });
  }

  send(message: string) {
    if (this.ws?.readyState === WebSocket.OPEN) {
      this.ws.send(message);
      return;
    }
    this.queue.push(message);
  }
}

referenceAnswer:
The queue is filled and flushed correctly; what is missing is any bound on it. Fix in three parts: store `{ body, queuedAt }` so entries can be aged out, cap the number kept, and pace the drain instead of emitting the whole array in one tick.

```ts
private flush() {
  const now = Date.now();
  const fresh = this.queue
    .filter((m) => now - m.queuedAt < 5 * 60_000)
    .slice(-50);
  const dropped = this.queue.length - fresh.length;
  this.queue = [];
  if (dropped > 0) this.onDropped(dropped);

  const pump = () => {
    const next = fresh.shift();
    if (!next || this.ws?.readyState !== WebSocket.OPEN) return;
    this.ws.send(next.body);
    setTimeout(pump, 50);
  };
  pump();
}
```

The product decision comes before the code: an hour-old chat message is usually not worth delivering at all, so the TTL is the part to agree on first, and the drop has to be visible in the UI rather than silent.

