function DataTable({ rows }: { rows: Row[] }) {
  const [selected, setSelected] = useState<Set<number>>(new Set());

  const toggle = (index: number) => {
    setSelected((prev) => {
      const next = new Set(prev);
      if (next.has(index)) {
        next.delete(index);
      } else {
        next.add(index);
      }
      return next;
    });
  };

  return (
    <tbody>
      {rows.map((row, index) => (
        <tr key={row.id}>
          <td>
            <input
              type="checkbox"
              checked={selected.has(index)}
              onChange={() => toggle(index)}
            />
          </td>
          <td>{row.name}</td>
        </tr>
      ))}
    </tbody>
  );
}

referenceAnswer:
The `key` is correct — `row.id` — but the selection set is keyed by array index, which is a property of the current ordering, not of the row. Fix: store ids.

```tsx
const [selected, setSelected] = useState<Set<string>>(new Set());

const toggle = (id: string) => {
  setSelected((prev) => {
    const next = new Set(prev);
    next.has(id) ? next.delete(id) : next.add(id);
    return next;
  });
};

// ...
<input checked={selected.has(row.id)} onChange={() => toggle(row.id)} />
```

With server-side paging this also decides what "select all" means: a set of ids can only ever describe the rows the client has loaded, so a true select-all across 50,000 rows has to be modelled as a filter predicate sent to the server, not as a set.

