function UploadPreview({ files }: { files: File[] }) {
  const [urls, setUrls] = useState<string[]>([]);

  useEffect(() => {
    setUrls(files.map((file) => URL.createObjectURL(file)));
  }, [files]);

  return (
    <div className="grid grid-cols-4 gap-2">
      {urls.map((url) => (
        <img key={url} src={url} alt="" />
      ))}
    </div>
  );
}

referenceAnswer:
An object URL holds a strong reference to its Blob until `URL.revokeObjectURL` is called or the document is discarded — the garbage collector cannot help, because the URL entry is the reference. With 20 MB photos, a few batches pin hundreds of megabytes. Fix by creating and revoking in the same effect:

```tsx
useEffect(() => {
  const next = files.map((file) => URL.createObjectURL(file));
  setUrls(next);
  return () => next.forEach(URL.revokeObjectURL);
}, [files]);
```

Note that the cleanup must revoke the URLs created by *that* run of the effect — reading them back out of state in the cleanup would revoke whatever the latest render happened to hold.

